        "Cuvântul este invariabil. Bitte schön este varianta mai politicoasă când oferi ceva („poftiți, vă rog”), bitte sehr — o variantă echivalentă. Wie bitte? înseamnă „poftim?”, când nu ai auzit bine.",
        "Substantivul die Bitte, scris cu majusculă, înseamnă „rugăminte” — este alt cuvânt."
