        "Forme: ich habe, du hast, er hat, wir haben, ihr habt, sie haben; hatte, hat gehabt. Haben este și verb auxiliar la perfectul compus (german): Ich habe das Buch gelesen.",
        "În multe expresii, haben descrie o stare: Hunger haben (a fi flămând), Durst haben, Angst haben, Recht haben (a avea dreptate)."
