      "layout": "standardStudy",
      "translation": "litru",
      "explanation": [
        "Ideea principală: der Liter este o unitate de măsură pentru volum — litrul. Se folosește când vorbim despre lichide: Milch, Wasser, Benzin.",
        "Plural: die Liter (fără terminație). După un numeral, unitatea de măsură nu se schimbă, iar substantivul următor vine fără prepoziție: zwei Liter Milch (doi litri de lapte), drei Liter Wasser. Der Liter este masculin; uneori se folosește și das Liter.",
        "Abrevierea este l: 1 l = 1000 Milliliter (ml, mililitri)."
      ],
      "examples": [
        {
          "de": "Ich kaufe zwei Liter Milch.",
          "lv": "Cumpăr doi litri de lapte."
        },
        {
          "de": "Wie viele Liter Wasser trinkst du am Tag?",
          "lv": "Câți litri de apă bei pe zi?"
        },
        {
          "de": "Das Auto braucht acht Liter auf hundert Kilometer.",
          "lv": "Mașina consumă opt litri la sută de kilometri."
        },
        {
          "de": "Die Flasche hat einen Liter Inhalt.",
          "lv": "Sticla are o capacitate de un litru."
        }
      ],
      "comparison": [
        {
          "word": "der Meter",
          "meaning": "metru",
          "example": "Der Tisch ist zwei Meter lang. – Masa are doi metri lungime."
        },
        {
          "word": "das Kilo",
          "meaning": "kilogram",
          "example": "Ich kaufe ein Kilo Äpfel. – Cumpăr un kilogram de mere."
        },
        {
          "word": "der Milliliter",
          "meaning": "mililitru",
          "example": "Ich brauche 200 Milliliter Milch. – Am nevoie de 200 de mililitri de lapte."
        }
      ],
      "tip": [
        "După numeral, unitatea de măsură rămâne neschimbată: zwei Liter (greșit: „zwei Liters”).",
        "Numele lichidelor urmează fără prepoziție: ein Liter Wasser (nu „ein Liter von Wasser”)."
      ],
      "important": [
        "Der Liter, die Liter — la plural nu se schimbă.",
        "O jumătate de litru se spune ein halber Liter (500 ml)."
      ],
